//! Integration control only: arbitrary raw inputs, not a failure-rate gate.
mod io;
use quantum_ecc::{circuit::{Op,OperationType as K},sim::Simulator};
use sha3::{Sha3_256,Digest,Shake256,digest::{Update,ExtendableOutput,XofReader}};
const NO:u64=u64::MAX;
fn dims(v:&[Op])->(usize,usize){let q=v.iter().flat_map(|o|[o.q_control1.0,o.q_control2.0,o.q_target.0]).filter(|&q|q!=NO).max().unwrap_or(0)as usize+1;let b=v.iter().flat_map(|o|[o.c_condition.0,o.c_target.0]).filter(|&q|q!=NO).max().unwrap_or(0)as usize+1;(q,b)}
fn rng(label:&str,batch:u64)->impl XofReader{let mut h=Shake256::default();h.update(label.as_bytes());h.update(&batch.to_le_bytes());h.finalize_xof()}
fn word(r:&mut impl XofReader)->u64{let mut x=[0u8;8];r.read(&mut x);u64::from_le_bytes(x)}
fn run(v:&[Op],batch:u64,input:&[(bool,usize,u64)],phase:u64,map:Option<&[u32]>)->(Vec<u64>,Vec<u64>,u64,u64,Vec<u8>){let(nq,nb)=dims(v);let count=v.iter().filter(|o|matches!(o.kind,K::R|K::Hmr)).count();let mut physical=rng("guard-schedule-control-physical-RNG-20261019",batch);let mut data=vec![0;count*8+64];physical.read(&mut data);let data=if let Some(map)=map{permute(&data,map)}else{data};let mut r=Bytes{data,at:0};let mut s=Simulator::new(nq,nb,&mut r);s.phase=phase;for &(q,i,value)in input{if q{s.qubits[i]=value}else{s.bits[i]=value}}s.apply_iter(v.iter());let state=(s.qubits.clone(),s.bits.clone(),s.phase,s.stats.toffoli_gates);drop(s);let mut tail=vec![0;64];r.read(&mut tail);assert_eq!(r.at,r.data.len());(state.0,state.1,state.2,state.3,tail)}
fn main(){let a:Vec<_>=std::env::args().collect();assert_eq!(a.len(),7);
 let original=io::load_ops(&a[1]);let converted=io::load_ops(&a[2]);let ordered=io::load_ops(&a[3]);let colored=io::load_ops(&a[4]);let old_nb=dims(&original).1;let raw=std::fs::read(&a[5]).unwrap();assert_eq!(&raw[..8],b"RNGPERM1");let count=u64::from_le_bytes(raw[8..16].try_into().unwrap())as usize;assert_eq!(&raw[16..80],hash(&original).as_bytes());assert_eq!(raw.len(),80+4*count);let map:Vec<_>=raw[80..].chunks_exact(4).map(|x|u32::from_le_bytes(x.try_into().unwrap())).collect();validate(&map);let old_events:Vec<_>=original.iter().filter(|o|matches!(o.kind,K::R|K::Hmr)).collect();let new_events:Vec<_>=ordered.iter().filter(|o|matches!(o.kind,K::R|K::Hmr)).collect();assert_eq!(old_events.len(),count);assert_eq!(new_events.len(),count);for(j,&i)in map.iter().enumerate(){let x=old_events[i as usize];let y=new_events[j];assert_eq!((x.kind,x.q_target,x.c_target),(y.kind,y.q_target,y.c_target));}
 let registered:std::collections::BTreeSet<_>=original.iter().filter(|o|o.kind==K::AppendToRegister&&o.q_target.0!=NO).map(|o|o.q_target.0 as usize).collect();let mut rows=vec![];
 for batch in 0..8{let mut r=rng("guard-schedule-control-uniform-raw-inputs-20261019",batch);let mut input=vec![];let mut seen=std::collections::BTreeSet::new();for o in &original{if o.kind==K::AppendToRegister{for(q,i)in [(true,o.q_target.0),(false,o.c_target.0)]{if i!=NO&&seen.insert((q,i)){input.push((q,i as usize,word(&mut r)));}}}}let phase=word(&mut r);
  let x=run(&original,batch,&input,phase,None);let y=run(&converted,batch,&input,phase,None);assert_eq!(x.0,y.0,"all original quantum wires after materialization");assert_eq!(x.1,&y.1[..old_nb],"all original classical bits after materialization");assert_eq!(x.2,y.2,"phase after materialization");assert_eq!(x.3,y.3,"executed Toffolis after materialization");assert_eq!(x.4,y.4,"physical RNG continuation after materialization");
  let z=run(&ordered,batch,&input,phase,Some(&map));assert_eq!(y,z,"all quantum/classical (including fresh bits), phase, cost and mapped-event continuation after scheduling");let w=run(&colored,batch,&input,phase,Some(&map));assert_eq!(z.1,w.1,"allocator classical bits including captured predicates");assert_eq!(z.2,w.2,"allocator phase");assert_eq!(z.3,w.3,"allocator executed Toffolis");assert_eq!(z.4,w.4,"allocator physical RNG continuation");for &q in &registered{assert_eq!(z.0[q],w.0[q],"registered quantum output");}
  let scratch=|v:&Vec<u64>|{let mut out:Vec<_>=v.iter().enumerate().filter(|(q,_)|!registered.contains(q)).map(|(_,x)|*x).collect();out.resize(dims(&original).0-registered.len(),0);out.sort_unstable();out};assert_eq!(scratch(&z.0),scratch(&w.0),"scratch-state multiset");rows.push(serde_json::json!({"batch":batch,"shots":64,"all_original_values_phase_cost_and_physical_RNG_equal_after_materialization":true,"all_values_including_fresh_classical_bits_equal_under_event_bijection":true,"colored_outputs_bits_phase_cost_RNG_and_scratch_equal":true}));
 }
 let result=serde_json::json!({"status":"PROTECTED_SIMULATOR_MATERIALIZED_GUARD_MAPPED_EVENT_TRANSCRIPT_CONTROL_PASS","scope":"512 raw assignments; converted circuit uses ordinary RNG, reordered circuit uses event bijection. Not an ordinary physical-RNG gate or resource score","rng_map_sha3_256":format!("{:x}",Sha3_256::digest(&raw)),"original_Q":dims(&original).0,"colored_Q":dims(&colored).0,"original_classical_bits":old_nb,"materialized_classical_bits":dims(&ordered).1,"rows":rows});std::fs::write(&a[6],serde_json::to_string_pretty(&result).unwrap()).unwrap();println!("all eight full materialized-guard mapped-event transcript controls pass");
}

struct Bytes{data:Vec<u8>,at:usize}impl XofReader for Bytes{fn read(&mut self,out:&mut[u8]){let end=self.at.checked_add(out.len()).unwrap();assert!(end<=self.data.len());out.copy_from_slice(&self.data[self.at..end]);self.at=end;}}
fn validate(map:&[u32]){let mut seen=vec![false;map.len()];for &x in map{assert!((x as usize)<map.len());assert!(!seen[x as usize]);seen[x as usize]=true;}assert!(seen.iter().all(|x|*x));}
fn permute(data:&[u8],map:&[u32])->Vec<u8>{validate(map);assert_eq!(data.len(),8*map.len()+64);let mut out=vec![];for &i in map{out.extend_from_slice(&data[8*i as usize..8*i as usize+8]);}out.extend_from_slice(&data[8*map.len()..]);out}
#[cfg(test)]mod tests{use super::*;
 #[test]fn event_words_and_final_continuation_are_preserved(){let data:Vec<_>=(0..80).collect();let x=permute(&data,&[1,0]);assert_eq!(&x[..8],&data[8..16]);assert_eq!(&x[8..16],&data[..8]);assert_eq!(&x[16..],&data[16..]);}
 #[test]#[should_panic]fn duplicate_event_is_rejected(){validate(&[0,0]);}
 #[test]#[should_panic]fn out_of_range_event_is_rejected(){validate(&[0,2]);}
 #[test]fn empty_map_retains_continuation(){assert_eq!(permute(&[1;64],&[]),vec![1;64]);}
}
fn hash(v:&[Op])->String{let mut h=Sha3_256::new();for o in v{for x in [o.kind as u64,o.q_control2.0,o.q_control1.0,o.q_target.0,o.c_target.0,o.c_condition.0,o.r_target.0]{Digest::update(&mut h,x.to_le_bytes());}}format!("{:x}",h.finalize())}